1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.util.E164PhoneNumbers;
12	
13	import java.time.LocalDate;
14	import java.time.Period;
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Map;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName",
26	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
27	    @Mapping(target = "initials",
28	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
29	            + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
30	    @Mapping(target = "membershipPoints",
31	        expression = "java(toMembershipPoints(owner))")
32	    @Mapping(target = "membershipLevel",
33	        expression = "java(toMembershipLevel(owner))")
34	    @Mapping(target = "locality",
35	        expression = "java(toLocality(owner))")
36	    @Mapping(target = "timezone",
37	        expression = "java(toTimezone(owner))")
38	    @Mapping(target = "contactPreference",
39	        expression = "java(toContactPreference(owner))")
40	    @Mapping(target = "identityKey",
41	        expression = "java(toIdentityKey(owner))")
42	    @Mapping(target = "checkDigit",
43	        expression = "java(toCheckDigit(owner))")
44	    @Mapping(target = "ageBand",
45	        expression = "java(toAgeBand(owner))")
46	    @Mapping(target = "telephoneDisplay",
47	        expression = "java(toTelephoneDisplay(owner))")
48	    @Mapping(target = "salutation",
49	        expression = "java(toSalutation(owner))")
50	    @Mapping(target = "fiscalYear",
51	        expression = "java(toFiscalYear(owner))")
52	    OwnerDto toOwnerDto(Owner owner);
53	
54	    /**
55	     * The fiscal year that the given date falls in, where the fiscal year starts on 1 July and is
56	     * identified by the calendar year in which it ends. A date on or after 1 July belongs to the
57	     * fiscal year ending in the following calendar year (e.g. 2026-08-01 -&gt; 2027), while a date
58	     * before 1 July belongs to the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt;
59	     * 2026). This is the single source of truth for the fiscal year used by both the DTO's
60	     * {@code fiscalYear} and the create endpoint's membership-number year segment.
61	     *
62	     * @param date the date to resolve, on a business day
63	     * @return the calendar year in which that date's fiscal year ends
64	     */
65	    static int fiscalYear(LocalDate date) {
66	        int year = date.getYear();
67	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? year + 1 : year;
68	    }
69	
70	    /**
71	     * The fiscal-year label for the given date, formatted {@code 'FY<YY>'} where YY is the last two
72	     * digits of the fiscal year (see {@link #fiscalYear(LocalDate)}), e.g. {@code 'FY27'}.
73	     *
74	     * @param date the date to resolve, on a business day
75	     * @return the {@code 'FY<YY>'} label for that date's fiscal year
76	     */
77	    static String fiscalYearLabel(LocalDate date) {
78	        return String.format("FY%02d", fiscalYear(date) % 100);
79	    }
80	
81	    /**
82	     * Derive an owner's fiscal year from its business-day-adjusted {@code registrationDate},
83	     * formatted {@code 'FY<YY>'} (see {@link #fiscalYearLabel(LocalDate)}). Returns {@code null} when
84	     * no registration date is present (the field is then absent from the DTO).
85	     */
86	    default String toFiscalYear(Owner owner) {
87	        LocalDate registrationDate = owner.getRegistrationDate();
88	        return registrationDate == null ? null : fiscalYearLabel(registrationDate);
89	    }
90	
91	    /**
92	     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
93	     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
94	     * just the last name.
95	     */
96	    default String toSalutation(Owner owner) {
97	        String lastName = owner.getLastName();
98	        String title = owner.getTitle();
99	        if (title == null || title.isBlank()) {
100	            return lastName;
101	        }
102	        return title + " " + lastName;
103	    }
104	
105	    /**
106	     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
107	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
108	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
109	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
110	     */
111	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
112	        LocalDate birthDate = owner.getBirthDate();
113	        if (birthDate == null) {
114	            return null;
115	        }
116	        LocalDate reference = owner.getRegistrationDate() != null
117	            ? owner.getRegistrationDate() : LocalDate.now();
118	        int age = Period.between(birthDate, reference).getYears();
119	        if (age < 18) {
120	            return OwnerDto.AgeBandEnum.MINOR;
121	        }
122	        if (age < 65) {
123	            return OwnerDto.AgeBandEnum.ADULT;
124	        }
125	        return OwnerDto.AgeBandEnum.SENIOR;
126	    }
127	
128	    /**
129	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
130	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
131	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
132	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
133	     *
134	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
135	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
136	     * code, a two-digit country code is assumed (the most common length).
137	     */
138	    default String toTelephoneDisplay(Owner owner) {
139	        String telephone = owner.getTelephone();
140	        if (telephone == null || !telephone.startsWith("+")) {
141	            return telephone;
142	        }
143	        String digits = telephone.substring(1);
144	        String code = E164PhoneNumbers.countryCode(digits)
145	            .filter(c -> digits.length() > c.length())
146	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
147	        String national = digits.substring(code.length());
148	        StringBuilder sb = new StringBuilder("+").append(code);
149	        for (int i = 0; i < national.length(); i += 3) {
150	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
151	        }
152	        return sb.toString();
153	    }
154	
155	    /**
156	     * Derive an owner's check digit: a single Luhn check digit (0-9) computed over the digits
157	     * contained in the {@code customerCode}. Non-digit characters (the separators) are ignored.
158	     */
159	    default Integer toCheckDigit(Owner owner) {
160	        String code = owner.getCustomerCode();
161	        if (code == null) {
162	            return null;
163	        }
164	        int sum = 0;
165	        boolean dbl = true;
166	        for (int i = code.length() - 1; i >= 0; i--) {
167	            char c = code.charAt(i);
168	            if (c < '0' || c > '9') {
169	                continue;
170	            }
171	            int d = c - '0';
172	            if (dbl) {
173	                d *= 2;
174	                if (d > 9) {
175	                    d -= 9;
176	                }
177	            }
178	            sum += d;
179	            dbl = !dbl;
180	        }
181	        return (10 - (sum % 10)) % 10;
182	    }
183	
184	    /**
185	     * Derive an owner's duplicate-detection identity key: the normalized E.164 telephone, the
186	     * lower-cased email (empty when none), and the household id (empty when none), joined with
187	     * {@code '|'}. Two owners are duplicates only when their whole identity keys are equal.
188	     *
189	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
190	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
191	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}.
192	     */
193	    default String toIdentityKey(Owner owner) {
194	        String email = hasEmail(owner) ? owner.getEmail() : "";
195	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
196	        return owner.getTelephone() + "|" + email + "|" + household;
197	    }
198	
199	    /**
200	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
201	     * for the "is an email present" rule shared by the derived fields below.
202	     */
203	    default boolean hasEmail(Owner owner) {
204	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
205	    }
206	
207	    /**
208	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
209	     * otherwise 'PHONE'.
210	     */
211	    default String toContactPreference(Owner owner) {
212	        return hasEmail(owner) ? "EMAIL" : "PHONE";
213	    }
214	
215	    /**
216	     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
217	     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
218	     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
219	     * is at least one elapsed fiscal year (see {@link #hasTenureBonus(Owner)}). Because a newly
220	     * created owner has zero tenure it never earns the tenure points, so a new owner with an email
221	     * and no namesakes in a single-member household scores 3 points.
222	     */
223	    default Integer toMembershipPoints(Owner owner) {
224	        int points = 0;
225	        if (hasEmail(owner)) {
226	            points += 2;
227	        }
228	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
229	        if (noNamesakes) {
230	            points += 1;
231	        }
232	        if (hasHouseholdBonus(owner)) {
233	            points += 2;
234	        }
235	        if (hasTenureBonus(owner)) {
236	            points += 3;
237	        }
238	        return points;
239	    }
240	
241	    /**
242	     * Whether the owner belongs to a household of 3 or more members. The household size is the count
243	     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
244	     * Returns {@code false} when no household size is present (e.g. legacy records).
245	     */
246	    default boolean hasHouseholdBonus(Owner owner) {
247	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
248	    }
249	
250	    /**
251	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
252	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
253	     * or more.
254	     */
255	    default Integer toMembershipLevel(Owner owner) {
256	        int points = toMembershipPoints(owner);
257	        if (points <= 1) {
258	            return 1;
259	        }
260	        if (points <= 3) {
261	            return 2;
262	        }
263	        if (points <= 5) {
264	            return 3;
265	        }
266	        return 4;
267	    }
268	
269	    /**
270	     * Whether the owner's tenure is at least one elapsed fiscal year, i.e. the fiscal year of the
271	     * current date is later than the fiscal year of the {@code registrationDate} (fiscal years start
272	     * on 1 July; see {@link #fiscalYear(LocalDate)}). A brand-new owner (registered in the current
273	     * fiscal year) has zero elapsed fiscal years and so never qualifies. Returns {@code false} when
274	     * no registration date is present.
275	     */
276	    default boolean hasTenureBonus(Owner owner) {
277	        LocalDate registrationDate = owner.getRegistrationDate();
278	        if (registrationDate == null) {
279	            return false;
280	        }
281	        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
282	    }
283	
284	    /**
285	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
286	     */
287	    Map<String, String> CITY_REGION = Map.of(
288	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
289	
290	    /**
291	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
292	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
293	     * inclusive.
294	     */
295	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
296	        "NSW", new int[] {2000, 2099},
297	        "VIC", new int[] {3000, 3099},
298	        "QLD", new int[] {4000, 4099});
299	
300	    /**
301	     * Derive an owner's locality (region) from the region-and-hash customer code: the {@code <REGION>}
302	     * segment of the {@code customerCode}, i.e. everything before the first {@code '-'}. Since the
303	     * region is baked into the customer code at creation (see the create endpoint), the locality now
304	     * moves with that identity rather than being recomputed from the postcode and city. When an owner
305	     * has no customer code yet (e.g. legacy records), fall back to deriving the region directly via
306	     * {@link #regionOf(Owner)}.
307	     */
308	    default String toLocality(Owner owner) {
309	        String code = owner.getCustomerCode();
310	        if (code != null) {
311	            int dash = code.indexOf('-');
312	            if (dash > 0) {
313	                return code.substring(0, dash);
314	            }
315	        }
316	        return regionOf(owner);
317	    }
318	
319	    /**
320	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
321	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
322	     */
323	    Map<String, String> REGION_TIMEZONE = Map.of(
324	        "NSW", "Australia/Sydney",
325	        "VIC", "Australia/Melbourne",
326	        "QLD", "Australia/Brisbane");
327	
328	    /**
329	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
330	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
331	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
332	     */
333	    default String toTimezone(Owner owner) {
334	        return REGION_TIMEZONE.get(toLocality(owner));
335	    }
336	
337	    /**
338	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
339	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
340	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
341	     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This is the region baked into
342	     * the {@code <REGION>} segment of a new owner's customer code and, through it, the owner's locality.
343	     */
344	    default String regionOf(Owner owner) {
345	        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
346	        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
347	        // type conversion and wrongly apply it to other String properties (e.g. telephone).
348	        String postcode = owner.getPostcode();
349	        if (postcode != null) {
350	            try {
351	                int value = Integer.parseInt(postcode.trim());
352	                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
353	                    int[] range = entry.getValue();
354	                    if (value >= range[0] && value <= range[1]) {
355	                        return entry.getKey();
356	                    }
357	                }
358	            }
359	            catch (NumberFormatException ignored) {
360	                // Non-numeric postcode: fall back to the city table below.
361	            }
362	        }
363	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
364	    }
365	
366	    Owner toOwner(OwnerDto ownerDto);
367	
368	    @Mapping(target = "id", ignore = true)
369	    @Mapping(target = "pets", ignore = true)
370	    Owner toOwner(OwnerFieldsDto ownerDto);
371	
372	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
373	
374	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
375	
376	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
377	        OwnerPageDto ownerPageDto = new OwnerPageDto();
378	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
379	        ownerPageDto.setPage(ownerPage.getNumber());
380	        ownerPageDto.setSize(ownerPage.getSize());
381	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
382	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
383	        return ownerPageDto;
384	    }
385	}
